pub fn host_lan_address(host: NonEmptyStr) -> Option<String> {
    fleet_intent_network().endpoints.clone().iter().cloned().fold(std::option::Option::None, |acc: _, e: Rc<NetworkEndpoint>| match acc.clone() {
    Some(v) => Some(v.clone()),
    std::option::Option::None => match (*e.subject.clone()).clone() {
    NetworkEndpointSubject::EndpointHost { host: h, .. } => if (crate::product_host_identity::host_identity_eq(h.clone(), host.clone()) && endpoint_is_host_lan(e.clone())) {
        Some(e.address.clone())
    } else {
        std::option::Option::None
    },
    NetworkEndpointSubject::EndpointAsset { asset: _, .. } => std::option::Option::None,
    NetworkEndpointSubject::EndpointSubjectUnregistered => std::option::Option::None,
},
})
}

pub fn endpoint_is_host_lan(e: Rc<NetworkEndpoint>) -> bool {
    (match e.role.clone() {
    NetworkAttachmentRole::HostOperatingSystem => true,
    NetworkAttachmentRole::BmcOutOfBand => false,
    NetworkAttachmentRole::ContainerBridgeDefault => false,
    NetworkAttachmentRole::ContainerBridgeSecondary => false,
    NetworkAttachmentRole::TailscaleEndpoint => false,
    NetworkAttachmentRole::LanGateway => false,
    NetworkAttachmentRole::FabricationAppliance => false,
} && match e.locality.clone() {
    NetworkLocality::Lan => true,
    NetworkLocality::Loopback => false,
    NetworkLocality::Internet => false,
    NetworkLocality::WslNat => false,
    NetworkLocality::WslBridged => false,
    NetworkLocality::DockerBridge => false,
    NetworkLocality::TailscaleOverlay => false,
})
}
